-- READ-ONLY exact-open-gap aggregate; bounded by frozen UTC candidate intervals.
SELECT gap_id,COUNT(*) AS source_rows,SUM(MOD(`dateTime`,300)=0) AS on_300s_grid,SUM(MOD(`dateTime`,300)<>0) AS off_300s_grid,COUNT(DISTINCT `usUnits`) AS distinct_usUnits,MIN(`usUnits`) AS min_usUnits,MAX(`usUnits`) AS max_usUnits,COUNT(DISTINCT `interval`) AS distinct_intervals,MIN(`interval`) AS min_interval,MAX(`interval`) AS max_interval,MIN(`dateTime`) AS first_source_ts,MAX(`dateTime`) AS last_source_ts,SUM(`outTemp` IS NOT NULL) AS nonnull_outTemp, SUM(`outHumidity` IS NOT NULL) AS nonnull_outHumidity, SUM(`rain` IS NOT NULL) AS nonnull_rain, SUM(`rainRate` IS NOT NULL) AS nonnull_rainRate, SUM(`windSpeed` IS NOT NULL) AS nonnull_windSpeed, SUM(`windGust` IS NOT NULL) AS nonnull_windGust, SUM(`barometer` IS NOT NULL) AS nonnull_barometer,SUM(`outTemp`=0) AS outTemp_zero_values FROM (SELECT CASE WHEN `dateTime`>1685274900 AND `dateTime`<1685332200 THEN 1 WHEN `dateTime`>1697018100 AND `dateTime`<1697025000 THEN 2 WHEN `dateTime`>1699510500 AND `dateTime`<1699561200 THEN 3 ELSE NULL END AS gap_id,`dateTime`,`usUnits`,`interval`,`outTemp`,`outHumidity`,`rain`,`rainRate`,`windSpeed`,`windGust`,`barometer` FROM `weewx_WH1080`.`archive` WHERE (`dateTime`>1685274900 AND `dateTime`<1685332200) OR (`dateTime`>1697018100 AND `dateTime`<1697025000) OR (`dateTime`>1699510500 AND `dateTime`<1699561200)) q WHERE gap_id IS NOT NULL GROUP BY gap_id ORDER BY gap_id;
